import{_ as r,C as d,o as a,c as i,j as o,a as n,E as l,a2 as s}from"./chunks/framework.DGvnA5EY.js";const u="/workbuddy-guide/assets/01-ai-team.Cbiocux2.png",x=JSON.parse('{"title":"本篇导读 · 第二篇 案例篇：从一项任务到一支 AI 团队","description":"> 内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利） 第一篇你学会了\\"每一个零件怎么用\\"——建任务、装技能、请专家、接账号、定自动化。 这一篇换一种学法：直接用真实场景把你拖下水。我们不教你新按钮…","frontmatter":{"title":"本篇导读 · 第二篇 案例篇：从一项任务到一支 AI 团队"},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/index.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/index.md","lastUpdated":1791625328000}'),c={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/index.md"};function p(g,t,q,h,b,k){const e=d("Paywall");return a(),i("div",null,[t[0]||(t[0]=o("h1",{id:"本篇导读-·-第二篇-案例篇-从一项任务到一支-ai-团队",tabindex:"-1"},[n("本篇导读 · 第二篇 案例篇：从一项任务到一支 AI 团队 "),o("a",{class:"header-anchor",href:"#本篇导读-·-第二篇-案例篇-从一项任务到一支-ai-团队","aria-label":'Permalink to "本篇导读 · 第二篇 案例篇：从一项任务到一支 AI 团队"'},"​")],-1)),t[1]||(t[1]=o("blockquote",null,[o("p",null,"内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利）")],-1)),l(e,{part:"2",variant:"banner"}),t[2]||(t[2]=s('<p>第一篇你学会了&quot;每一个零件怎么用&quot;——建任务、装技能、请专家、接账号、定自动化。 这一篇换一种学法：<strong>直接用真实场景把你拖下水</strong>。我们不教你新按钮，而是带你跑通 一件件具体的事：写一份 Word、理一遍乱桌面、不在电脑前也能让它干活、把每天的新闻 汇成一条推送、把会议录音变成行动清单……</p><p>做完这 11 个案例，你会发现 WorkBuddy 已经不是&quot;一个工具&quot;，而像<strong>一支随叫随到的 AI 小队</strong>——你发一句话，它就分头去办。</p><p><img src="'+u+'" alt="一只小黑站在前方，身后跟着几个举着不同工具的小黑影子，像一支小队" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解&quot;从一项任务到一支 AI 团队&quot;，与实际软件界面无关。</em></p><h2 id="贯穿全篇的一个理念-零成本-skill" tabindex="-1">贯穿全篇的一个理念：零成本 Skill <a class="header-anchor" href="#贯穿全篇的一个理念-零成本-skill" aria-label="Permalink to &quot;贯穿全篇的一个理念：零成本 Skill&quot;">​</a></h2><p>这一篇反复会提到&quot;零成本 Skill&quot;，先讲清楚它是什么，后面你就不陌生了。</p><p>所谓&quot;零成本&quot;，不是免费蹭，而是<strong>不花一分钱、不用写一行代码，把你的经验变成可复用的工具</strong>：</p><ol><li><strong>先用现成的免费技能把任务跑通。</strong> SkillHub 上有很多免费技能，装好即调用， 不用额外配置。新手最该先装的有几个&quot;黄金组合&quot;：<code>pdf</code>（读长文/提取/合并/水印）、 <code>xlsx</code>（读写 Excel/清洗/图表）、<code>pptx</code>（生成 PPT）、<code>docx</code>（写 Word）、 <code>browser-automation</code>（替你点网页/抓数据）、<code>腾讯文档</code>（在线协作）、 <code>find-skills</code>（<strong>技能雷达</strong>，告诉它你的工作流，它帮你挑该装哪些）。</li><li><strong>跑顺之后，用 <code>skill-creator</code> 把你的 SOP 固化成&quot;只属于你&quot;的技能。</strong> 你用自然语言描述需求，它自动生成技能文件。比如你每周都做&quot;团建策划&quot;， 就把它做成技能，下次只说主题就能出初稿——这是&quot;零成本&quot;的精髓。</li><li><strong><code>find-skills</code> 当参谋</strong>：不知道有没有现成技能时，问它&quot;我经常要处理发票， 有什么合适的技能？&quot;，它帮你配装。</li></ol><blockquote><p>装技能的三条铁律：<strong>认准官方源</strong>（优先 SkillHub 官方市场，腾讯做过安全过滤）； <strong>警惕野路子</strong>（陌生人私发的技能文件别直接跑，先验源、看权限、查评价）； <strong>同类装一个就够</strong>（装多了占资源还可能指令冲突）。</p></blockquote><h2 id="本篇每个案例的统一读法-五问定标" tabindex="-1">本篇每个案例的统一读法：五问定标 <a class="header-anchor" href="#本篇每个案例的统一读法-五问定标" aria-label="Permalink to &quot;本篇每个案例的统一读法：五问定标&quot;">​</a></h2><p>多数&quot;AI 做得不好&quot;的案例，根因不是模型不行，是人没把交付标准说清。所以每个案例 开头我都用这五个问题给任务定标，你照着填，跑出来的东西就靠谱得多：</p><table tabindex="0"><thead><tr><th>问题</th><th>要说清什么</th><th>示例</th></tr></thead><tbody><tr><td><strong>目标</strong></td><td>这份产出要帮谁做什么决定</td><td>给部门负责人看，判断项目是否继续投入</td></tr><tr><td><strong>受众</strong></td><td>阅读者是谁、懂不懂背景</td><td>管理层只看结论；项目组要过程和责任人</td></tr><tr><td><strong>材料</strong></td><td>哪些是事实来源、哪些只是参考</td><td><code>data.xlsx</code> 是唯一数据口径，旧版只参考结构</td></tr><tr><td><strong>格式</strong></td><td>要 Word、Excel、PPT，还是三者联动</td><td>一份复盘 Word + 一张风险台账 Excel</td></tr><tr><td><strong>验收</strong></td><td>怎么判断结果可用</td><td>数字能回源、公式可刷新、PPT 投屏不溢出</td></tr></tbody></table><p>每个案例的正文结构也固定为六块：<strong>痛点 → 先选对 Skill（组合表）→ 真实可复制 提示词 → 执行步骤表 → 实际效果 → 验收标准</strong>。你能直接照抄的提示词，都用代码块 给出，方括号 <code>【】</code> 里是占位符，换成你自己的内容即可。</p><h2 id="怎么读这一篇" tabindex="-1">怎么读这一篇 <a class="header-anchor" href="#怎么读这一篇" aria-label="Permalink to &quot;怎么读这一篇&quot;">​</a></h2><p>不用从头读到尾，<strong>按你的痛点挑</strong>：</p><ul><li>天天和文档打交道 → 先看第 11 章（办公三件套）</li><li>电脑桌面一团乱 → 第 12 章（整理文件）</li><li>经常不在电脑前 → 第 13 章（远程控制）</li><li>想让信息自动找你 → 第 15 章（资讯整合）</li><li>收藏了一堆却用不上 → 第 16 章（知识管理）</li><li>会议多、纪要烦 → 第 17 章（会议）</li><li>想看看投资 / 视频 / 自媒体 / GEO → 第 18–21 章</li></ul><h2 id="一条安全底线-全篇通用" tabindex="-1">一条安全底线（全篇通用） <a class="header-anchor" href="#一条安全底线-全篇通用" aria-label="Permalink to &quot;一条安全底线（全篇通用）&quot;">​</a></h2><p>动文件、资金、账号之前，<strong>先确认再执行</strong>；删除之前必须出清单、先备份；公共 Wi-Fi 下不发敏感指令。AI 很听指令，但&quot;不可逆操作&quot;这道闸得你自己守。</p><h2 id="本章任务清单" tabindex="-1">本章任务清单 <a class="header-anchor" href="#本章任务清单" aria-label="Permalink to &quot;本章任务清单&quot;">​</a></h2><ul><li>[ ] 翻完本篇目录，圈出最戳你痛点的 3 个案例</li><li>[ ] 在 SkillHub 先装好 <code>find-skills</code>，让它给你的工作流配一套技能包</li><li>[ ] 选 1 个案例，今天就照着跑通一次，并记一句话：哪里顺、哪里卡</li></ul><hr><p><em>下一篇：第 11 章——办公三件套：Word、Excel、PPT，多数人第一次感受到 AI 价值的地方。</em></p><hr><p><em>本指南为第三方非官方整理，版权归作者所有，转载请注明出处。</em></p>',24)),l(e,{part:"2"}),t[3]||(t[3]=o("p",null,[o("em",null,"—— 以上试读到此为止。第二篇共 11 章，完整版 PDF 包含全部实操内容。——")],-1))])}const P=r(c,[["render",p]]);export{x as __pageData,P as default};
